def ui_text(text, lang):
    if lang not in ('ru','en') or not text:
        return text
    stripped=text.strip()
    if not stripped:return text
    mapping=UI_EN if lang=='en' else UI_RU
    translated=mapping.get(stripped)
    if translated is not None:
        return text[:len(text)-len(text.lstrip())]+translated+text[len(text.rstrip()):]
    # A date is data, but its UI prefix must follow the selected language.
    if stripped.startswith('☎ Показати номер'):
        return text.replace('Показати номер',mapping.get('Показати номер','Показати номер'),1)
    if stripped.startswith('Статус: '):
        return text.replace('Статус: ',mapping.get('Статус:','Статус:')+' ',1).replace('open',mapping.get('Відкрито','open')).replace('closed',mapping.get('Закрито','closed'))
    if stripped.startswith('Звернення №'):
        return text.replace('Звернення №',{'ru':'Обращение №','en':'Request #'}[lang],1)
    if stripped.startswith('Опубліковано: '):
        return text.replace('Опубліковано: ', mapping.get('Опубліковано','Опубліковано')+': ', 1)
    if stripped.startswith('Відкрити фото ') and stripped[len('Відкрити фото '):].isdigit():
        return text.replace('Відкрити фото ',{'ru':'Открыть фото ','en':'Open photo '}[lang],1)
    if stripped.startswith('Фото товару ') and stripped[len('Фото товару '):].isdigit():
        return text.replace('Фото товару ',{'ru':'Фото товара ','en':'Item photo '}[lang],1)
    if stripped.startswith('Чати (') and stripped.endswith(')'):
        return text.replace('Чати (', mapping.get('Чати','Чати')+' (', 1)
    if stripped.startswith('Початкова ціна: ') and ' · Поточна: ' in stripped:
        terms={'ru':(('Початкова ціна:', 'Начальная цена:'),(' · Поточна:', ' · Текущая:'),(' · Прихований мінімум:', ' · Скрытый минимум:'),('Активних діб:', 'Активных дней:'),('До наступного кроку', 'До следующего снижения'),(' діб ', ' дней '),(' год.', ' ч.')),
               'en':(('Початкова ціна:', 'Starting price:'),(' · Поточна:', ' · Current:'),(' · Прихований мінімум:', ' · Private minimum:'),('Активних діб:', 'Active days:'),('До наступного кроку', 'Until next reduction'),(' діб ', ' days '),(' год.', ' h.'))}
        for original,replacement in terms[lang]:text=text.replace(original,replacement)
        return text
    if stripped.startswith('Місто: ') and ' · Автор: ' in stripped:
        return text.replace('Місто: ',{'ru':'Город: ','en':'City: '}[lang],1).replace(' · Автор: ',{'ru':' · Автор: ','en':' · Author: '}[lang],1)
    # Dynamic interface strings are translated, while their free-text data remain unchanged.
    if stripped.endswith(' — Одна Друга'):
        first=stripped[:-len(' — Одна Друга')]
        localized=mapping.get(first,first)
        return text.replace(stripped,localized+' — Одна Друга')
    if lang=='en':
        if stripped.startswith('Помилка '):return text.replace('Помилка ','Error ',1)
        if stripped.startswith('+ Додати'):return text.replace('+ Додати','+ Post',1)
        if stripped.startswith('Ціна (грн'):return text.replace('Ціна (грн','Price (UAH',1)
        if ' / ' in stripped and stripped.startswith(('Куплю / ','Продам / ')):
            return ' / '.join(mapping.get(part,part) for part in text.split(' / '))
        return text
    if stripped.startswith('Помилка '):
        return text.replace('Помилка ','Ошибка ',1)
    if stripped.startswith('+ Додати'):
        return text.replace('+ Додати', '+ Добавить', 1)
    if stripped.startswith('Чати ('):
        return text.replace('Чати (','Чаты (',1)
    if stripped.startswith('Ціна (грн'):
        return text.replace('Ціна (грн','Цена (грн',1).replace('за домовленістю','по договорённости')
    if stripped.startswith('Бюджет (грн'):
        return text.replace('за домовленістю','по договорённости')
    if ' / ' in stripped and stripped.startswith(('Куплю / ','Продам / ')):
        return ' / '.join(UI_RU.get(part,part) for part in text.split(' / '))
    if stripped in ('buy · active','sell · active','buy · closed','sell · closed'):
        mode,_,status=stripped.partition(' · ')
        return ('Куплю' if mode=='buy' else 'Продам')+' · '+('Активное' if status=='active' else 'Закрытое')
    # Mixed UI content: keep user-entered names, prices and counts unchanged.
    replacements=(
        ('Кількість користувачів:', 'Количество пользователей:'),
        (' · оголошень:', ' · объявлений:'),
        (' · повідомлень:', ' · сообщений:'),
        (' · до ', ' · до '),
        (' · днів · ', ' · дней · '),
        ('Чат із ', 'Чат с '),
        ('Пропозиція: ', 'Предложение: '),
        ('Місто: ', 'Город: '),
        (' · Автор: ', ' · Автор: '),
        (' · ', ' · '),
    )
    for src,dst in replacements:
        if src in text: text=text.replace(src,dst)
    # Counters and dynamic status in UI.
    text=re.sub(r'(?<=\d) повідомлень\b',' сообщений',text)
    text=re.sub(r'\b(\d+) днів\b',r'\1 дней',text)
    if text.strip().startswith('Код надіслано на '):
        text=text.replace('Код надіслано на ','Код отправлен на ').replace('Термін дії — 10 хвилин. Поверніться до форми та введіть код.', 'Действует 10 минут. Вернитесь к форме и введите код.')
    return text


def locale_html(html_source, lang):
    if lang not in ('ru','en'):return html_source
    # Skip scripts and styles. Translate static markup text/labels without rewriting data stored in DB.
    tag_or_text=re.compile(r'(?is)<script\b[^>]*>.*?</script\s*>|<style\b[^>]*>.*?</style\s*>|<textarea\b[^>]*>.*?</textarea\s*>|<span data-i18n-skip>.*?</span\s*>|<[^>]*>|[^<]+')
    attribute=re.compile(r'(?i)\b(placeholder|aria-label|title|alt)=(?P<q>[\"\'])(?P<val>.*?)(?P=q)')
    def rewrite(m):
        token=m.group(0)
        if token.startswith('<'):
            if token.lower().startswith(('<script','<style','<textarea','<span data-i18n-skip>')):return token
            def attr(a):
                src=html.unescape(a.group('val'))
                dst=ui_text(src,lang)
                return a.group(1)+'='+a.group('q')+html.escape(dst,quote=True)+a.group('q')
            return attribute.sub(attr,token)
        return ui_text(token,lang)
    return tag_or_text.sub(rewrite,html_source)


