def db():
    c = sqlite3.connect(str(DB_PATH), timeout=25, isolation_level=None)
    c.row_factory = sqlite3.Row
    c.execute('PRAGMA busy_timeout=25000')
    c.execute('PRAGMA foreign_keys=ON')
    return c


def init_db():
    with db() as c:
        c.execute('PRAGMA journal_mode=WAL')
        c.executescript('''
        CREATE TABLE IF NOT EXISTS users (id INTEGER PRIMARY KEY, email TEXT UNIQUE NOT NULL, name TEXT NOT NULL,
           pwd TEXT NOT NULL, phone TEXT DEFAULT '',show_buy INTEGER DEFAULT 0,show_sell INTEGER DEFAULT 0,
           is_admin INTEGER DEFAULT 0,created INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS sessions (sid TEXT PRIMARY KEY, user_id INTEGER REFERENCES users(id),
           csrf TEXT NOT NULL, lang TEXT DEFAULT 'uk',created INTEGER NOT NULL,expires INTEGER NOT NULL,
           code_hash TEXT,code_email TEXT,code_expires INTEGER,code_tries INTEGER DEFAULT 0,last_code INTEGER DEFAULT 0);
        CREATE TABLE IF NOT EXISTS ads (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id),
          mode TEXT NOT NULL,category TEXT NOT NULL,subcategory TEXT DEFAULT '',product_type TEXT DEFAULT '',
          title TEXT NOT NULL,description TEXT DEFAULT '', city TEXT NOT NULL, price INTEGER DEFAULT 0,
          images TEXT DEFAULT '[]',status TEXT DEFAULT 'active',created INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS messages (id INTEGER PRIMARY KEY, ad_id INTEGER NOT NULL REFERENCES ads(id),
          sender_id INTEGER NOT NULL REFERENCES users(id),recipient_id INTEGER NOT NULL REFERENCES users(id),
          body TEXT DEFAULT '',price INTEGER DEFAULT 0,photos TEXT DEFAULT '[]',created INTEGER NOT NULL,read_at INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS favorites (user_id INTEGER NOT NULL REFERENCES users(id), ad_id INTEGER NOT NULL REFERENCES ads(id),
          PRIMARY KEY(user_id,ad_id));
        CREATE TABLE IF NOT EXISTS ad_unique_views (
          ad_id INTEGER NOT NULL, visitor TEXT NOT NULL, created INTEGER NOT NULL,
          PRIMARY KEY(ad_id,visitor));
        CREATE TABLE IF NOT EXISTS ad_phone_reveals (
          ad_id INTEGER NOT NULL, visitor TEXT NOT NULL, created INTEGER NOT NULL,
          PRIMARY KEY(ad_id,visitor));
        CREATE TABLE IF NOT EXISTS promotions (id INTEGER PRIMARY KEY, owner_id INTEGER NOT NULL REFERENCES users(id),
          ad_id INTEGER NOT NULL REFERENCES ads(id),service TEXT NOT NULL,created INTEGER NOT NULL,expires INTEGER NOT NULL,price INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS services (id TEXT PRIMARY KEY, enabled INTEGER NOT NULL DEFAULT 0,
           price INTEGER NOT NULL DEFAULT 0,days INTEGER NOT NULL DEFAULT 5);
        CREATE TABLE IF NOT EXISTS email_throttle (email TEXT PRIMARY KEY, last_sent INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS search_history (id INTEGER PRIMARY KEY, query TEXT NOT NULL, created INTEGER NOT NULL);
        CREATE TABLE IF NOT EXISTS analytics_events (id INTEGER PRIMARY KEY, visitor TEXT NOT NULL,
           created INTEGER NOT NULL, kind TEXT NOT NULL, path TEXT NOT NULL,
           country TEXT NOT NULL DEFAULT 'Невідомо', source TEXT NOT NULL DEFAULT 'Невідомо',
           device TEXT NOT NULL DEFAULT 'Невідомо', browser TEXT NOT NULL DEFAULT 'Невідомо');
        CREATE TABLE IF NOT EXISTS support_tickets (
            id INTEGER PRIMARY KEY, public_token TEXT NOT NULL UNIQUE,
            user_id INTEGER REFERENCES users(id), email TEXT NOT NULL DEFAULT '',
            subject TEXT NOT NULL, category TEXT NOT NULL DEFAULT 'other',
            status TEXT NOT NULL DEFAULT 'open', created INTEGER NOT NULL,
            updated INTEGER NOT NULL, admin_seen INTEGER NOT NULL DEFAULT 0,
            user_seen INTEGER NOT NULL DEFAULT 0);
        CREATE TABLE IF NOT EXISTS support_messages (
            id INTEGER PRIMARY KEY, ticket_id INTEGER NOT NULL REFERENCES support_tickets(id),
            is_admin INTEGER NOT NULL DEFAULT 0, body TEXT NOT NULL DEFAULT '',
            photo TEXT NOT NULL DEFAULT '', created INTEGER NOT NULL);
        CREATE INDEX IF NOT EXISTS idx_support_updated ON support_tickets(updated);
        CREATE TABLE IF NOT EXISTS analytics_settings (key TEXT PRIMARY KEY, value TEXT NOT NULL);
        CREATE TABLE IF NOT EXISTS registration_attribution (
            user_id INTEGER PRIMARY KEY, visitor TEXT NOT NULL, created INTEGER NOT NULL,
            source TEXT NOT NULL DEFAULT 'Невідомо', country TEXT NOT NULL DEFAULT 'Невідомо');
        CREATE INDEX IF NOT EXISTS idx_regattr_time ON registration_attribution(created);
        CREATE INDEX IF NOT EXISTS idx_analytics_time ON analytics_events(created);
        CREATE INDEX IF NOT EXISTS idx_analytics_vis ON analytics_events(visitor,created);
        CREATE INDEX IF NOT EXISTS idx_ad_mode ON ads(mode,created);
        CREATE INDEX IF NOT EXISTS idx_msg_rec ON messages(recipient_id,created);
        ''')
        # Existing V38 databases lack read_at. Preserve all messages and avoid flagging
        # the entire historic inbox as new when upgrading.
        cols={r['name'] for r in c.execute('PRAGMA table_info(messages)').fetchall()}
        if 'read_at' not in cols:
            c.execute('ALTER TABLE messages ADD COLUMN read_at INTEGER NOT NULL DEFAULT 0')
            c.execute('UPDATE messages SET read_at=created')
        c.execute('CREATE INDEX IF NOT EXISTS idx_msg_unread ON messages(recipient_id,read_at)')
        adcols={r['name'] for r in c.execute('PRAGMA table_info(ads)').fetchall()}
        if 'item_condition' not in adcols:
            c.execute("ALTER TABLE ads ADD COLUMN item_condition TEXT NOT NULL DEFAULT ''")
            adcols.add('item_condition')
        pricecols={
            'initial_price':'INTEGER NOT NULL DEFAULT 0',
            'min_price':'INTEGER NOT NULL DEFAULT 0',
            'active_since':'INTEGER NOT NULL DEFAULT 0',
            'active_elapsed':'INTEGER NOT NULL DEFAULT 0',
            'price_steps':'INTEGER NOT NULL DEFAULT 0',
            'floor_reached_elapsed':'INTEGER NOT NULL DEFAULT 0'
        }
        migration=any(k not in adcols for k in pricecols)
        for key,definition in pricecols.items():
            if key not in adcols:c.execute(f'ALTER TABLE ads ADD COLUMN {key} {definition}')
        if migration:
            # Old ads have no seller-approved minimum; hold at current price until they edit.
            ts=int(time.time())
            c.execute('UPDATE ads SET initial_price=price,min_price=price,active_since=CASE WHEN status=? THEN ? ELSE 0 END,active_elapsed=0,price_steps=0,floor_reached_elapsed=0 WHERE initial_price=0',('active',ts))

        for key, *_ in SERVICES:
            c.execute('INSERT OR IGNORE INTO services(id,enabled,price,days) VALUES (?,0,0,5)',(key,))
        # Local test only: an existing account with the owner email must be able
        # to open the monetization panel after upgrading an earlier test database.
        # Never grant admin access this way in a public deployment.
        if TEST_1111 and ADMIN_EMAIL:
            c.execute('UPDATE users SET is_admin=1 WHERE lower(email)=?',(ADMIN_EMAIL,))
init_db()


def esc(x): return html.escape(str(x if x is not None else ''), quote=True)
def h(s): return esc(s)
def user_display(s): return '<span data-i18n-skip>'+esc(s)+'</span>'
def now(): return int(time.time())

def publication_datetime(timestamp):
    # SQLite stores Unix timestamps (UTC). Show Ukrainian local wall-clock time, including DST.
    return datetime.datetime.fromtimestamp(int(timestamp), datetime.timezone.utc).astimezone(ZoneInfo('Europe/Kyiv')).strftime('%d.%m.%Y, %H:%M')


PRICE_PERIOD = 5 * 24 * 3600  # Five ACTIVE days, not calendar days.

def active_duration(ad,ts=None):
    ts=now() if ts is None else ts
    return max(0,int(ad['active_elapsed'] or 0)) + (max(0,ts-int(ad['active_since'])) if ad['status']=='active' and ad['active_since'] else 0)

def next_price(current,floor):
    # Integer hryvnia: nearest integer, always a real reduction until the floor.
    if current<=floor:return floor
    return max(floor,min(current-1,int(current*0.99+0.5)))

def refresh_prices(ts=None):
    ts=now() if ts is None else ts
    with WRITE_LOCK,db() as c:
        rows=c.execute("SELECT * FROM ads WHERE status='active' AND mode='sell' AND price>0 AND active_since>0").fetchall()
        for ad in rows:
            target=active_duration(ad,ts)//PRICE_PERIOD
            elapsed_steps=max(0,int(target)-int(ad['price_steps'] or 0))
            if not elapsed_steps:continue
            current=int(ad['price']);floor=int(ad['min_price'])
            # Stop as soon as floor is reached; do not reset the history.
            for _ in range(min(elapsed_steps,3000)):
                if current<=floor:break
                current=next_price(current,floor)
            reached=int(ad['floor_reached_elapsed'] or 0)
            if current<=floor and int(ad['price'])>floor:
                reached=int(target)*PRICE_PERIOD
            c.execute('UPDATE ads SET price=?,price_steps=?,floor_reached_elapsed=? WHERE id=?',(current,int(target),reached,ad['id']))

def hash_pwd(password):
    salt = secrets.token_bytes(16)
    derived = hashlib.scrypt(password.encode(),salt=salt,n=2**14,r=8,p=1,dklen=32)
    return 'scrypt$'+base64.b64encode(salt).decode()+'$'+base64.b64encode(derived).decode()
def verify_pwd(password, stored):
    try:
        _,salt,expected=stored.split('$')
        d=hashlib.scrypt(password.encode(),salt=base64.b64decode(salt),n=2**14,r=8,p=1,dklen=32)
        return hmac.compare_digest(d,base64.b64decode(expected))
    except (ValueError,TypeError): return False


def parse_post(env):
    size=int(env.get('CONTENT_LENGTH') or 0)
    if size>28*1024*1024: raise ValueError('Занадто велике завантаження (до 28 МБ).')
    data=env['wsgi.input'].read(size)
    ctype=env.get('CONTENT_TYPE','')
    if ctype.startswith('multipart/form-data'):
        raw=b'Content-Type: '+ctype.encode('latin1')+b'\r\nMIME-Version: 1.0\r\n\r\n'+data
        msg=BytesParser(policy=email_policy).parsebytes(raw)
        fields={}; files=[]
        if not msg.is_multipart(): raise ValueError('Некоректне завантаження')
        for part in msg.iter_parts():
            name=part.get_param('name',header='content-disposition')
            filename=part.get_filename()
            content=part.get_payload(decode=True) or b''
            if filename:
                if name=='photos': files.append((filename, content))
            elif name:
                fields[name]=content.decode('utf-8','replace')
        return fields, files
    return {k:v[-1] for k,v in parse_qs(data.decode('utf-8','replace'),keep_blank_values=True).items()}, []


def store_photos(files, limit):
    if len(files)>limit: raise ValueError(f'Максимум {limit} фото')
    names=[]
    try:
        for original,content in files:
            if len(content)>5*1024*1024: raise ValueError('Фото більше 5 МБ')
            if content.startswith(b'\xff\xd8\xff'): ext='.jpg'
            elif content.startswith(b'\x89PNG\r\n\x1a\n'): ext='.png'
            elif content[:4]==b'RIFF' and content[8:12]==b'WEBP': ext='.webp'
            else: raise ValueError('Дозволені лише JPG, PNG і WebP')
            name=uuid.uuid4().hex+ext
            # Exclusive creation prevents overwrites, path derived solely from UUID.
            with (UPLOADS/name).open('xb') as f:f.write(content)
            names.append(name)
    except Exception:
        for x in names: (UPLOADS/x).unlink(missing_ok=True)
        raise
    return names


def decode_sid(env):
    jar=cookies.SimpleCookie()
    try: jar.load(env.get('HTTP_COOKIE',''))
    except Exception: pass
    return jar.get('odnasid').value if jar.get('odnasid') else ''

def sid_session(env):
    sid=decode_sid(env)
    with db() as c:
        row=c.execute('SELECT * FROM sessions WHERE sid=? AND expires>?',(sid,now())).fetchone() if sid else None
        if row: return dict(row),False
        sid=secrets.token_urlsafe(32); csrf=secrets.token_urlsafe(32)
        c.execute('INSERT INTO sessions(sid,csrf,created,expires) VALUES (?,?,?,?)',(sid,csrf,now(),now()+30*86400))
        row=c.execute('SELECT * FROM sessions WHERE sid=?',(sid,)).fetchone()
        return dict(row),True


def url(path,**q): return path+('?' + urlencode(q) if q else '')
def encode_img(x): return '/uploads/'+quote(x)
def route_env(env):
    return env.get('PATH_INFO','/') or '/', {k:v[-1] for k,v in parse_qs(env.get('QUERY_STRING',''),keep_blank_values=True).items()}

