class HTTPError(Exception):
    def __init__(self, status, message): self.status,self.message=status,message


def status_str(n): return {200:'200 OK',302:'302 Found',303:'303 See Other',400:'400 Bad Request',401:'401 Unauthorized',403:'403 Forbidden',404:'404 Not Found',405:'405 Method Not Allowed',413:'413 Payload Too Large',429:'429 Too Many Requests',500:'500 Internal Server Error',503:'503 Service Unavailable'}.get(n,str(n)+' Error')

def response(start,body,status=200,content_type='text/html; charset=utf-8',headers=None):
    if isinstance(body,str):body=body.encode('utf-8')
    head=[('Content-Type',content_type),('Content-Length',str(len(body))),('X-Content-Type-Options','nosniff'),('X-Frame-Options','SAMEORIGIN'),('Referrer-Policy','strict-origin-when-cross-origin'),('Content-Security-Policy',"default-src 'self'; img-src 'self' data: blob:; style-src 'self' 'unsafe-inline'; script-src 'self' 'unsafe-inline'; base-uri 'self'; form-action 'self'")]
    if headers:head.extend(headers)
    start(status_str(status),head);return [body]

def redirect(start,path,headers=None):
    return response(start,'',303,headers=[('Location',path)]+(headers or []))

def csrf_input(sess): return f'<input type="hidden" name="csrf" value="{esc(sess["csrf"])}">'
def form_btn(text,action,session,extra='',cls='btn'):
    confirm = (' onsubmit="return confirm(&quot;'+esc(ui_text('Видалити оголошення, його фотографії та всі чати назавжди? Цю дію не можна скасувати.',session.get('lang','uk')))+'&quot;)"'
               if re.fullmatch(r'/ad/\d+/delete',action) else '')
    return f'<form method="post" action="{action}" style="display:inline"{confirm}>{csrf_input(session)}{extra}<button class="{cls}">{esc(text)}</button></form>'

def unread_total(user_id):
    if not user_id:return 0
    with db() as c:
        return int(c.execute('SELECT COUNT(*) AS n FROM messages WHERE recipient_id=? AND read_at=0',(user_id,)).fetchone()['n'])


def unread_label(n,lang):
    if lang=='ru':return f'Чаты: непрочитано — {n}' if n else 'Чаты: нет новых сообщений'
    if lang=='en':return f'Chats: {n} unread' if n else 'Chats: no new messages'
    return f'Чати: непрочитаних — {n}' if n else 'Чати: немає нових повідомлень'


