def serve_home(sess,user,q):
    mode=q.get('mode','sell');mode=mode if mode in ('all','sell','buy') else 'sell'
    cat=q.get('cat','');sub=q.get('sub','');typ=q.get('type','');text=q.get('q','').strip()[:150]
    if text:
        with db() as c:c.execute('INSERT INTO search_history(query,created) VALUES(?,?)',(text,now()))
    lang=sess['lang'];ua=lang!='ru'
    T=lambda uk,ru:uk if ua else ru
    date_label={'uk':'Опубліковано','ru':'Опубликовано','en':'Published'}.get(lang,'Опубліковано')
