def analytics_source(env):
    # Use utm_source when present; otherwise classify referrer. Do not claim referrers are always present.
    query=parse_qs(env.get('QUERY_STRING',''))
    hint=(query.get('utm_source',[''])[0] or '').lower()[:80]
    ref=(env.get('HTTP_REFERER','') or '').lower()[:400]
    for name, tokens in [('TikTok',('tiktok','vm.tiktok')),('Instagram',('instagram','instagr.am')),('YouTube',('youtube','youtu.be')),('Facebook',('facebook','fb.com')),('Google',('google.',)),('Telegram',('telegram','t.me'))]:
        if any(x in hint or x in ref for x in tokens):return name
    if hint:return 'Інше (UTM)'
    if not ref:return 'Прямий / невідомо'
    if 'odnadruga.com.ua' in ref or '127.0.0.1' in ref or '192.168.' in ref:return 'Внутрішній'
    return 'Інші сайти'

# Country-level GeoIP is cached only in process memory. Never persist visitor IPs.
_GEO_COUNTRY_CACHE = {}
_GEO_LOCK = threading.RLock()


def analytics_country(env):
    countries={'UA':'Україна','PL':'Польща','DE':'Німеччина','US':'США',
               'GB':'Велика Британія','FR':'Франція','CZ':'Чехія',
               'IT':'Італія','ES':'Іспанія','CA':'Канада',
               'NL':'Нідерланди','RO':'Румунія','MD':'Молдова'}
    # This header is trusted only if ingress via Cloudflare is separately locked down.
    if os.environ.get('TRUST_CF_COUNTRY','0')=='1':
        v=(env.get('HTTP_CF_IPCOUNTRY') or '').upper()
        if re.fullmatch('[A-Z]{2}',v) and v not in ('XX','T1'):
            return countries.get(v,v)
    # Railway's public HTTP edge overwrites X-Real-IP; do not use client-provided XFF.
    # GEOIP_RAILWAY=1 should only be enabled if the app is reachable via the public HTTP edge.
    if os.environ.get('GEOIP_RAILWAY','0')!='1':
        return 'Невідомо'
    raw=(env.get('HTTP_X_REAL_IP') or '').strip()
    try:
        address=ipaddress.ip_address(raw)
        if not address.is_global:
            return 'Невідомо'
    except ValueError:
        return 'Невідомо'
    # Consult an HTTPS country-level geo API only once per IP per process per day.
    # No full IP is written to the application's database or logs.
    with _GEO_LOCK:
        old=_GEO_COUNTRY_CACHE.get(raw)
        if old and old[0]>time.time():
            return old[1]
    result='Невідомо'
    try:
        req=urllib.request.Request('https://ipwho.is/'+quote(raw,safe='')+'?fields=success,country_code',
                                   headers={'User-Agent':'OdnaDruga-country-analytics/1.0'})
        with urllib.request.urlopen(req,timeout=1.5) as r:
            payload=json.loads(r.read(2048).decode('utf-8'))
        code=str(payload.get('country_code') or '').upper() if payload.get('success') else ''
        if re.fullmatch('[A-Z]{2}',code):
            result=countries.get(code,code)
    except (OSError,ValueError,TypeError,KeyError):
        pass
    with _GEO_LOCK:
        if len(_GEO_COUNTRY_CACHE)>5000:
            _GEO_COUNTRY_CACHE.clear()
        _GEO_COUNTRY_CACHE[raw]=(time.time()+(86400 if result!='Невідомо' else 600),result)
    return result


def analytics_device(env):
    agent=(env.get('HTTP_USER_AGENT') or '').lower()
    device='Планшет' if ('ipad' in agent or 'tablet' in agent) else ('Телефон' if any(x in agent for x in ('iphone','android','mobile')) else ('Комп’ютер' if agent else 'Невідомо'))
    browser='Edge' if 'edg/' in agent else 'Chrome' if 'chrome/' in agent else 'Firefox' if 'firefox/' in agent else 'Safari' if 'safari/' in agent else 'Інший / невідомо'
    return device,browser

def record_visit(env,sess,path):
    # Local browser cookie is anonymous identifier; not a fingerprint. Counts cannot identify people precisely.
    if env.get('REQUEST_METHOD')!='GET' or not (path=='/' or path=='/info' or re.fullmatch(r'/ad/\d+',path)):
        return
    ts=now();visitor=sess['sid'];device,browser=analytics_device(env)
    with db() as c:
        last=c.execute('SELECT created,source,country FROM analytics_events WHERE visitor=? AND kind=? ORDER BY id DESC LIMIT 1',(visitor,'visit')).fetchone()
        source=analytics_source(env)
        if source in ('Внутрішній','Прямий / невідомо') and last:source=last['source']
        country=analytics_country(env)
        if country=='Невідомо' and last:country=last['country']
        # New visit when no page activity for 30 min; a visit is not a person.
        activity=c.execute('SELECT created FROM analytics_events WHERE visitor=? ORDER BY id DESC LIMIT 1',(visitor,)).fetchone()
        if not activity or ts-activity['created']>=1800:
            c.execute('INSERT INTO analytics_events(visitor,created,kind,path,country,source,device,browser) VALUES(?,?,?,?,?,?,?,?)',(visitor,ts,'visit',path,country,source,device,browser))
        c.execute('INSERT INTO analytics_events(visitor,created,kind,path,country,source,device,browser) VALUES(?,?,?,?,?,?,?,?)',(visitor,ts,'page',path,country,source,device,browser))

def stats_periods(sess):
    q=parse_qs(sess.get('query_string',''))
    return q

def serve_admin_stats(sess,user,period='7d'):
    require_user(user)
    if not user['is_admin']:raise HTTPError(403,'Лише для адміністратора')
    period=period if period in ('today','7d','30d','all') else '7d'
    ts=now()
    # Current timezone is local server timezone; display this explicitly.
    if period=='today':
        d=datetime.datetime.fromtimestamp(ts).replace(hour=0,minute=0,second=0,microsecond=0)
        since=int(d.timestamp())
    elif period=='7d':since=ts-7*86400
    elif period=='30d':since=ts-30*86400
    else:since=0
    with db() as c:
        reset_row=c.execute("SELECT value FROM analytics_settings WHERE key='reset_at'").fetchone()
        reset_at=int(reset_row['value']) if reset_row else 0
        if reset_at>since: since=reset_at
        cond=' AND created>=?' if since else ''
        pr=(since,) if since else ()
        events=c.execute('SELECT * FROM analytics_events WHERE 1=1'+cond+' ORDER BY created',pr).fetchall()
        visits=[e for e in events if e['kind']=='visit']
        pages=[e for e in events if e['kind']=='page']
        visitors=len({e['visitor'] for e in visits})
        visit_count=len(visits)
        page_count=len(pages)
        online=c.execute('SELECT COUNT(DISTINCT visitor) n FROM analytics_events WHERE created>=?',(ts-300,)).fetchone()['n']
        def breakdown(field):
            result={}
            for e in visits:
                key=e[field] or 'Невідомо';result[key]=result.get(key,0)+1
            return sorted(result.items(),key=lambda item:-item[1])
        sources=breakdown('source');countries=breakdown('country');devices=breakdown('device');browsers=breakdown('browser')
        combos={}
        for e in visits:
            key=(e['country'],e['source']);combos[key]=combos.get(key,0)+1
        combo_rows=sorted(combos.items(),key=lambda kv:-kv[1])
        n_users=c.execute('SELECT COUNT(*) n FROM users').fetchone()['n']
        n_ads=c.execute('SELECT COUNT(*) n FROM ads').fetchone()['n']
        n_sells=c.execute("SELECT COUNT(*) n FROM ads WHERE mode='sell'").fetchone()['n']
        n_buys=c.execute("SELECT COUNT(*) n FROM ads WHERE mode='buy'").fetchone()['n']
        n_msgs=c.execute('SELECT COUNT(*) n FROM messages').fetchone()['n']
        n_prom=c.execute('SELECT COUNT(*) n FROM promotions WHERE expires>?',(ts,)).fetchone()['n']
        new_users=c.execute('SELECT COUNT(*) n FROM users WHERE created>=?',(since,)).fetchone()['n'] if since else n_users
        new_ads=c.execute('SELECT COUNT(*) n FROM ads WHERE created>=?',(since,)).fetchone()['n'] if since else n_ads
        new_msgs=c.execute('SELECT COUNT(*) n FROM messages WHERE created>=?',(since,)).fetchone()['n'] if since else n_msgs
        registrations_by_source=c.execute('SELECT source,COUNT(*) n FROM registration_attribution'+(' WHERE created>=?' if since else '')+' GROUP BY source ORDER BY n DESC',pr).fetchall()
        # Ad-detail page views are grounded in actual page events, not extrapolated.
        ad_view_counts={}
        for e in pages:
            m=re.fullmatch(r'/ad/(\d+)',e['path'] or '')
            if m:ad_view_counts[int(m.group(1))]=ad_view_counts.get(int(m.group(1)),0)+1
        popular_categories={}
        if ad_view_counts:
            ids=list(ad_view_counts)
            for ad in c.execute('SELECT id,category FROM ads WHERE id IN ('+','.join('?' for _ in ids)+')',ids).fetchall():
                label=ad['category'] or 'Невідомо'
                popular_categories[label]=popular_categories.get(label,0)+ad_view_counts[ad['id']]
        popular_categories=sorted(popular_categories.items(),key=lambda kv:-kv[1])
        searches=c.execute("SELECT query,COUNT(*) n FROM search_history WHERE query<>''"+(' AND created>=?' if since else '')+" GROUP BY query ORDER BY n DESC LIMIT 12",pr).fetchall()
    buttons=' '.join('<a class="btn" href="/admin/stats?period='+x+'" style="'+('background:#167e49;color:#fff' if period==x else '')+'">'+label+'</a>' for x,label in [('today','Сьогодні'),('7d','7 днів'),('30d','30 днів'),('all','Весь час')])
    def metric(v,label):return '<div class="panel" style="min-width:140px;flex:1"><strong style="font-size:26px">'+str(v)+'</strong><p>'+label+'</p></div>'
    def table(headers,rows):
        if not rows:return '<p>Поки немає даних.</p>'
        return '<div style="overflow-x:auto"><table style="width:100%;border-collapse:collapse"><tr>'+''.join('<th style="text-align:left;padding:9px;border-bottom:1px solid var(--line)">'+esc(t)+'</th>' for t in headers)+'</tr>'+''.join('<tr>'+''.join('<td style="padding:9px;border-bottom:1px solid var(--line)">'+esc(ui_text(str(v),sess['lang']) if headers!=['Запит','Кількість'] else str(v))+'</td>' for v in row)+'</tr>' for row in rows)+'</table></div>'
    groups={}
    for e in visits:
        dt=datetime.datetime.fromtimestamp(e['created'])
        key=dt.strftime('%H:00') if period=='today' else (dt.strftime('%Y-%m') if period=='all' else dt.strftime('%d.%m'))
        groups[key]=groups.get(key,0)+1
    graph=''
    for label,n in sorted(groups.items()):
        maxv=max(groups.values()) if groups else 1
        graph+='<div class="row" style="gap:10px;align-items:center;margin:6px 0"><span style="min-width:70px">'+label+'</span><span style="height:12px;background:#167e49;border-radius:3px;display:inline-block;width:'+str(max(2,round(n/maxv*70)))+'%"></span><strong>'+str(n)+'</strong></div>'
    body='<h1>Статистика · Адміністратор</h1><p class="sub">Відвідуваність сайту та активність користувачів</p><div class="row" style="flex-wrap:wrap">'+buttons+'</div>'
    body+='<div class="panel"><h2>Відвідувачі</h2><div class="row" style="flex-wrap:wrap;gap:12px">'+metric(visitors,'Унікальні відвідувачі (браузери)')+metric(visit_count,'Візити')+metric(page_count,'Перегляди сторінок')+metric(online,'Онлайн за 5 хв')+'</div></div>'
    body+='<div class="panel"><h2>Динаміка відвідувань</h2>'+(graph or '<p>Поки немає відвідувань.</p>')+'</div>'
    def bars(title,rows):
        if not rows:return '<div class="panel"><h2>'+title+'</h2><p>Поки немає даних.</p></div>'
        maximum=max(v for _,v in rows) or 1
        parts=[]
        for label,count in rows[:12]:
            width=max(1,round(100*count/maximum))
            parts.append('<div class="analytic-line"><div class="analytic-label"><span>'+esc(ui_text(str(label),sess['lang']))+'</span><strong>'+str(count)+'</strong></div><div class="analytic-track"><div class="analytic-fill" style="width:'+str(width)+'%"></div></div></div>')
        return '<div class="panel"><h2>'+title+'</h2>'+''.join(parts)+'</div>'
    body+=bars('Країни відвідувачів',countries)
    body+=bars('Джерела переходів',sources)
    source_visits=dict(sources)
    source_registrations={r['source']:r['n'] for r in registrations_by_source}
    source_rows=[(source,n,source_registrations.get(source,0)) for source,n in sources]
    for source,n in source_registrations.items():
        if source not in source_visits:source_rows.append((source,0,n))
    body+='<div class="panel"><h2>Джерело → відвідування → реєстрації</h2>'+table(['Джерело','Візити','Реєстрації'],source_rows)+'<p class="sub">Джерело реєстрації фіксується з цієї версії. Історичні реєстрації не приписуються джерелам заднім числом.</p></div>' 
    body+='<div class="panel"><h2>Країна + джерело переходу</h2>'+table(['Країна','Джерело','Візити'],[(a,b,n) for (a,b),n in combo_rows])+'</div>'
    body+='<div class="stats-duo">'+bars('Пристрої',devices)+bars('Браузери',browsers)+'</div>'
    body+=bars('Популярні категорії за переглядами оголошень',popular_categories)
    body+='<div class="panel"><h2>Активність маркетплейсу</h2><div class="row" style="gap:12px;flex-wrap:wrap">'+''.join([metric(n_users,'Користувачі — всього'),metric(new_users,'Нові реєстрації'),metric(n_ads,'Оголошення — всього'),metric(new_ads,'Нові оголошення'),metric(n_sells,'Продам — всього'),metric(n_buys,'Куплю — всього'),metric(n_msgs,'Повідомлення — всього'),metric(new_msgs,'Нові повідомлення'),metric(n_prom,'Активні просування')])+'</div></div>'
    body+='<div class="panel"><h2>Що шукають</h2>'+table(['Запит','Кількість'],[(r['query'],r['n']) for r in searches])+'</div>'
    body+='<p class="sub">Візити рахуються за анонімним браузерним ідентифікатором; це не точна кількість людей. Джерело може бути приховано браузером. Країна визначається за публічним IP через HTTPS GeoIP, якщо в Railway встановлено GEOIP_RAILWAY=1. Для локальних IP та помилок сервісу показується «Невідомо». GeoIP може помилятися або бути обмеженим провайдером. Часові інтервали використовують часовий пояс сервера. Дані накопичуються тільки після встановлення V48.</p>'
    body+='''<details class="panel"><summary><strong>Скинути статистику</strong> — лише адміністратор</summary>
    <p class="sub">Видаляється історія відвідувань, пошуків і атрибуції реєстрацій. Аккаунти, оголошення, повідомлення, просування та налаштування НЕ видаляються. Загальні кількості існуючих аккаунтів та оголошень лишаться правдивими.</p>
    <form method="post" action="/admin/stats/reset">'''+csrf_input(sess)+'''<label>Для підтвердження напишіть RESET:
    <input name="confirmation" autocomplete="off" required pattern="RESET" placeholder="RESET"></label>
    <button class="btn" type="submit">Скинути аналітику</button></form></details>'''
    if reset_at:
        body+='<p class="sub">Аналітика відраховується від останнього скидання. Загальні кількості користувачів, оголошень та повідомлень не обнуляються, адже записи залишаються в базі.</p>'
    body+='<p><a class="btn" href="/admin">Монетизація</a> <a class="btn" href="/cabinet">Кабінет</a></p>'
    return body

def serve_admin(sess,user,saved=False):
    require_user(user)
    if not user['is_admin']:raise HTTPError(403,'Лише для адміністратора')
    with db() as c:
        n_users=c.execute('SELECT COUNT(*) n FROM users').fetchone()['n'];n_ads=c.execute('SELECT COUNT(*) n FROM ads').fetchone()['n'];n_msgs=c.execute('SELECT COUNT(*) n FROM messages').fetchone()['n']
        services=c.execute('SELECT * FROM services WHERE id IN ('+','.join('?' for _ in SERVICES)+')',[x[0] for x in SERVICES]).fetchall()
    body=f'<h1>Монетизація · Адміністратор</h1>'+('<p class="notice" style="border-color:#27a06d;font-weight:700">✓ Налаштування послуги збережено</p>' if saved else '')+f'<p class="notice">Кількість користувачів: {n_users} · оголошень: {n_ads} · повідомлень: {n_msgs}</p><div class="panel"><h2>Шість незалежних послуг</h2><p class="sub">П’ять для «Продам», окреме виділення для «Куплю». Тільки увімкнені послуги доступні користувачам; кожна має власні ціну та строк. Тариф 0 грн — безкоштовний тест, це не дохід. Платежі за ненульові тарифи ще не підключені. Вимкнення не скасовує вже активні просування.</p>'
    services={x['id']:x for x in services}
    for sid, _, _ in SERVICES:
        p=services[sid]
        label,desc=next(((s[1],s[2]) for s in SERVICES if s[0]==p['id']),('Послуга',''))
        body+=f'''<form class="panel" method="post" action="/admin/service" onsubmit="const b=this.querySelector('button[type=submit]');b.textContent='Зберігаємо…';b.style.opacity='0.75';">{csrf_input(sess)}<input type="hidden" name="service" value="{p['id']}"><strong>{esc(label)}</strong><p class="sub">{esc(desc)}</p><label><input type="checkbox" name="enabled" {'checked' if p['enabled'] else ''}> Увімкнено</label><div class="row"><label>Ціна (грн) <input style="width:100px" type="number" min="0" max="999999" name="price" value="{p['price']}"></label><label>Днів <input style="width:85px" type="number" min="1" max="365" name="days" value="{p['days']}"></label><button type="submit" class="btn primary">Зберегти</button></div></form>'''
    with db() as c:
        active=c.execute('SELECT COUNT(*) n FROM promotions WHERE expires>?',(now(),)).fetchone()['n']
        free=c.execute('SELECT COUNT(*) n FROM promotions WHERE price=0').fetchone()['n']
        searches=c.execute("SELECT query,COUNT(*) n FROM search_history WHERE query<>'' GROUP BY query ORDER BY n DESC LIMIT 8").fetchall()
        own_ads=c.execute("SELECT id,title FROM ads WHERE owner_id=? AND status='active' ORDER BY id DESC LIMIT 100",(user['id'],)).fetchall()
    body+=f'<div class="panel"><h3>Статистика та журнал</h3><p>Активні просування: {active} · Безкоштовні активації: {free} (0 грн не є доходом).</p><p>Пошукові запити: '+(', '.join(esc(x['query'])+' ('+str(x['n'])+')' for x in searches) if searches else 'поки немає')+'</p></div>'
    body+='<div class="panel"><h3>Бонусне оформлення для власника</h3><p class="caption">Тільки адміністратор призначає своїм оголошенням безкоштовний бірюзовий бонус. На картці не буде написів «Реклама» або «Бонусне».</p>'
    if own_ads:
        body+=f'<form method="post" action="/admin/bonus">{csrf_input(sess)}<label class="field">Оголошення<select name="ad_id">'+''.join(f'<option value="{r["id"]}">№{r["id"]} — {esc(r["title"])}</option>' for r in own_ads)+'</select></label><label class="field">Днів<input type="number" name="days" value="7" min="1" max="365"></label><button class="btn primary">Надати бонус</button></form>'
    else:body+='<p class="caption">Спочатку створіть оголошення у власному акаунті.</p>'
    return body+'</div></div>'

def send_verification(email,purpose,code,lang='uk'):
    if EMAIL_MODE=='dev' and APP_ENV=='local':
        print(f'[LOCAL TEST] Email code for {email} ({purpose}): {code}',flush=True)
        return
    api_key=os.environ.get('RESEND_API_KEY','').strip()
    mail_from=os.environ.get('MAIL_FROM','').strip()
    if not api_key or not mail_from:raise HTTPError(503,'Для відправлення email потрібно налаштувати RESEND_API_KEY і MAIL_FROM.')
    payload=json.dumps({'from':mail_from,'to':[email], 'subject':('Код подтверждения — Одна Друга' if lang=='ru' else 'Код підтвердження — Одна Друга'),
         'html':(f'<p>Ваш код для сайта Одна Друга:</p><h2>{code}</h2><p>Код действителен 10 минут.</p>' if lang=='ru' else f'<p>Ваш код для сайту Одна Друга:</p><h2>{code}</h2><p>Код дійсний 10 хвилин.</p>')}).encode()
    req=urllib.request.Request('https://api.resend.com/emails',data=payload,headers={'Authorization':'Bearer '+api_key,'Content-Type':'application/json','User-Agent':'odnadruga/1.0'},method='POST')
    try:
        with urllib.request.urlopen(req,timeout=15) as resp:
            if resp.status not in (200,201,202):
                raise HTTPError(503,'Сервіс Resend не підтвердив надсилання листа.')
            resp.read()
        print('[EMAIL] Resend accepted a confirmation email request.',flush=True)
    except urllib.error.HTTPError as ex:
        # If the normal urllib request is blocked at the HTTP edge, retry once
        # through a direct HTTPS connection (without urllib proxy discovery).
        # A 403 means Resend did not accept the first send, so this does not
        # repeat an accepted email. Never log authorization or message body.
        if ex.code == 403:
            try:
                import http.client
                conn = http.client.HTTPSConnection('api.resend.com', timeout=15)
                try:
                    conn.request('POST', '/emails', body=payload, headers={
                        'Authorization': 'Bearer ' + api_key,
                        'Content-Type': 'application/json',
                        'User-Agent': 'odnadruga/1.0',
                        'Accept': 'application/json',
                    })
                    direct_response = conn.getresponse()
                    direct_status = direct_response.status
                    direct_type = direct_response.getheader('Content-Type', '')[:70]
                    direct_response.read(4096)
                finally:
                    conn.close()
                print(f'[EMAIL DIAGNOSTIC] Direct HTTPS retry status={direct_status}; content_type={direct_type}', flush=True)
                if direct_status in (200, 201, 202):
                    print('[EMAIL] Resend accepted confirmation via direct HTTPS.', flush=True)
                    return
            except (OSError, TimeoutError, http.client.HTTPException) as direct_err:
                print(f'[EMAIL DIAGNOSTIC] Direct HTTPS retry failed: {type(direct_err).__name__}', flush=True)
        # Log only safe diagnostics: never expose API keys, email addresses, or verification codes.
        raw_body = ex.read(4096)
        content_type = (ex.headers.get('Content-Type', '') if ex.headers else '').split(';')[0][:60]
        request_id = (ex.headers.get('x-resend-request-id', '') if ex.headers else '')
        if not request_id and ex.headers:
            request_id = ex.headers.get('cf-ray', '')
        try:
            error_body = json.loads(raw_body.decode('utf-8', 'replace'))
            error_name = str(error_body.get('name', 'unknown')) if isinstance(error_body, dict) else 'unknown'
            error_message = str(error_body.get('message', 'not provided')) if isinstance(error_body, dict) else 'not provided'
        except (ValueError, UnicodeError, OSError):
            error_name = 'non_json_response'
            error_message = 'Body was not JSON; check response content type and proxy restrictions.'
        def safe_resend_diagnostic(value):
            value = re.sub(r'(?i)re_[a-z0-9_\\-]+', '[REDACTED_KEY]', value)
            value = re.sub(r'(?i)bearer\\s+\\S+', '[REDACTED_TOKEN]', value)
            value = re.sub(r'[A-Za-z0-9._%+\\-]+@[A-Za-z0-9.\\-]+\\.[A-Za-z]{2,}', '[REDACTED_EMAIL]', value)
            value = re.sub(r'\\b\\d{6}\\b', '[REDACTED_CODE]', value)
            value = re.sub(r'https?://\\S+', '[REDACTED_URL]', value)
            value = re.sub(r'[\\r\\n\\t]+', ' ', value)
            return value[:240]
        print(
            f'[EMAIL ERROR] Resend HTTP {ex.code}; '
            f'type={safe_resend_diagnostic(error_name)}; '
            f'detail={safe_resend_diagnostic(error_message)}; '
            f'content_type={safe_resend_diagnostic(content_type)}; '
            f'request_id={safe_resend_diagnostic(request_id)}',
            flush=True
        )
        if ex.code == 401:
            raise HTTPError(503, 'Resend не прийняв API-ключ. Перевірте RESEND_API_KEY.')
        if ex.code == 403:
            raise HTTPError(503, 'Resend заборонив відправлення (403). Перевірте причину в журналах Railway.')
        if ex.code in (400, 404, 422):
            raise HTTPError(503, 'Resend відхилив параметри листа. Перевірте MAIL_FROM і журнал Railway.')
        if ex.code == 429:
            raise HTTPError(503, 'Перевищено ліміт поштового сервісу Resend. Перевірте його панель керування.')
        raise HTTPError(503, 'Resend не прийняв листа. Перевірте журнал Railway.')
    except (urllib.error.URLError, TimeoutError, OSError):
        print('[EMAIL ERROR] Cannot connect to Resend. Check internet connection.',flush=True)
        raise HTTPError(503,'Немає зв’язку з Resend. Перевірте підключення комп’ютера до інтернету.')


def authorize(sess):
    if not sess.get('user_id'):return None
    with db() as c:
        r=c.execute('SELECT * FROM users WHERE id=?',(sess['user_id'],)).fetchone()
        return dict(r) if r else None


def process_request(env,start):
    path,q=route_env(env)
    method=env.get('REQUEST_METHOD','GET').upper()
    if path=='/healthz':return response(start,json.dumps({'ok':True,'server':'v44-local-complete-test-1111'}),content_type='application/json')
    if path.startswith('/assets/'):
        name=path[len('/assets/'):]
        if name not in ('emblem.png','favicon.ico','apple-touch-icon.png'):raise HTTPError(404,'Не знайдено')
        file=ROOT/'assets'/name
        return response(start,file.read_bytes(),content_type=mimetypes.guess_type(name)[0] or 'application/octet-stream',headers=[('Cache-Control','public, max-age=86400')])
    if path.startswith('/uploads/'):
        name=path[len('/uploads/'):]
        if not re.fullmatch(r'[a-f0-9]{32}\.(jpg|png|webp)',name):raise HTTPError(404,'Не знайдено')
        file=UPLOADS/name
        if not file.is_file():raise HTTPError(404,'Фото не знайдено')
        return response(start,file.read_bytes(),content_type=mimetypes.guess_type(name)[0] or 'image/jpeg',headers=[('Cache-Control','public,max-age=86400')])
    # Server owns the current price; UI displays only its persisted value.
    if not (path.startswith('/assets/') or path.startswith('/uploads/')):refresh_prices()
    sess,new_session=sid_session(env)
    record_visit(env,sess,path)
    user=authorize(sess)
    headers=[]
    if new_session:
        cookie=f'odnasid={sess["sid"]}; Path=/; Max-Age=2592000; HttpOnly; SameSite=Lax'+('; Secure' if IS_HTTPS else '')
        headers=[('Set-Cookie',cookie)]
    def page(content,title='Одна Друга',status=200,msg=''):
        return response(start,render_layout(content,sess,user,title,notice=msg,hide_mobile_add=(path == '/new' or bool(re.fullmatch(r'/ad/\d+/edit', path)))),status,headers=headers)
    def go(target):return redirect(start,target,headers)
    if method=='GET' and path=='/api/unread':
        payload=json.dumps({'unread':unread_total(user['id']) if user else 0})
        return response(start,payload,content_type='application/json; charset=utf-8',headers=headers+[('Cache-Control','no-store')])
    if method=='GET':
        if path=='/info':return page(serve_info(sess),'Інформація')
        if path=='/support':return page(serve_support(sess,user,q),'Підтримка')
        if path=='/support/admin':return page(serve_support_admin(user),'Звернення')
        ticket_match=re.fullmatch(r'/support/t/(\d+)',path)
        if ticket_match:return page(serve_support_ticket(sess,user,int(ticket_match[1]),q),'Звернення')
        if not user and (path in ('/cabinet','/new','/inbox','/admin','/admin/stats','/favorites') or path.startswith('/chat/') or re.fullmatch(r'/ad/\d+/edit',path)):
            return go('/login')
        match_user=re.fullmatch(r'/user/(\d+)',path)
        if match_user:return page(serve_public_profile(sess,user,int(match_user[1])),'Публічний профіль')
        if path=='/':return page(serve_home(sess,user,q),'Головна')
        if path in ('/register','/login','/reset','/login-code'):return page(serve_auth(sess,path.strip('/')),{'register':'Реєстрація','login':'Вхід','reset':'Відновлення пароля','login-code':'Вхід за кодом email'}[path.strip('/')])
        if path=='/new':return page(serve_new(sess,user,q),'Нове оголошення')
        if path=='/cabinet':return page(serve_cabinet(sess,user),'Кабінет')
        if path=='/inbox':return page(serve_inbox(sess,user),'Чати')
        if path=='/admin':return page(serve_admin(sess,user,saved=(q.get('service_saved')=='1')),'Монетизація')
        if path=='/admin/stats':return page(serve_admin_stats(sess,user,q.get('period','7d')),'Статистика')
        if path=='/favorites':
            require_user(user)
            with db() as c:
                rows=c.execute('SELECT a.id,a.title,a.mode,a.city,a.images FROM favorites f JOIN ads a ON f.ad_id=a.id WHERE f.user_id=? ORDER BY a.id DESC',(user['id'],)).fetchall()
            favorite_items=[]
            for r in rows:
                photos=json.loads(r['images'] or '[]')
                thumb=(f'<img src="{encode_img(photos[0])}" alt="" loading="lazy" style="width:88px;height:88px;object-fit:cover;flex:none;border-radius:10px">' if photos else '<span aria-hidden="true" style="width:88px;height:88px;flex:none;border-radius:10px;display:grid;place-items:center;background:var(--surface,#e5e7eb);border:1px solid #9ca3af">▧</span>')
                favorite_items.append(f'<a href="/ad/{r["id"]}" style="display:flex;align-items:center;gap:14px;padding:12px 0;text-decoration:none;color:inherit;min-width:0;border-bottom:1px solid #9ca3af55">{thumb}<span style="min-width:0"><strong style="display:block;overflow-wrap:anywhere">{user_display(r["title"])}</strong><span class="sub" style="display:block;margin-top:6px">{user_display(r["city"])}</span></span></a>')
            content='<h1>Обране</h1><div class="panel">'+''.join(favorite_items)+'</div>'
            return page(content,'Обране')
        match=re.fullmatch(r'/ad/(\d+)',path)
        if match:
            ad_id=int(match[1])
            with db() as c:
                owner=c.execute('SELECT owner_id FROM ads WHERE id=?',(ad_id,)).fetchone()
                if owner and (not user or owner['owner_id'] != user['id']):
                    c.execute('INSERT OR IGNORE INTO ad_unique_views(ad_id,visitor,created) VALUES(?,?,?)',(ad_id,sess['sid'],now()))
            return page(serve_ad(sess,user,ad_id),'Оголошення')
        match=re.fullmatch(r'/ad/(\d+)/edit',path)
        if match:
            require_user(user)
            with db() as c:r=c.execute('SELECT * FROM ads WHERE id=? AND owner_id=?',(match[1],user['id'])).fetchone()
            if not r:raise HTTPError(404,'Немає такого власного оголошення')
